#!/usr/bin/env node
/**
 * Registry generator for .claude/registry/
 *
 * Scans components, hooks, utils, and pages under overrides/app/ and writes
 * structured markdown tables that Claude Code reads instead of grepping the
 * codebase.
 *
 * Usage:
 *   node scripts/generateRegistry.mjs              # Full regeneration
 *   node scripts/generateRegistry.mjs --file=PATH  # Incremental — regenerate
 *                                                    # only the category for PATH
 *   node scripts/generateRegistry.mjs --fresh      # Full regeneration, ignoring
 *                                                    # the base/override consumer
 *                                                    # caches (forces recompute)
 */

import {readFileSync, writeFileSync, readdirSync, existsSync, mkdirSync} from 'fs'
import {join, dirname, basename, extname, relative} from 'path'
import {fileURLToPath} from 'url'
import {execSync} from 'child_process'
import {createHash} from 'crypto'

const __dirname = dirname(fileURLToPath(import.meta.url))
const ROOT = join(__dirname, '..')
const APP = join(ROOT, 'overrides/app')
const BASE_PKG = join(ROOT, 'node_modules/@salesforce/retail-react-app')
const BASE_APP = join(BASE_PKG, 'app')
const REGISTRY = join(ROOT, '.claude/registry')
const BASE_CACHE = join(REGISTRY, '.baseCache.json')
const OVERRIDE_CACHE = join(REGISTRY, '.overrideCache.json')

if (!existsSync(REGISTRY)) mkdirSync(REGISTRY, {recursive: true})

const fileArg = process.argv.find((a) => a.startsWith('--file='))?.slice(7)
const fresh = process.argv.includes('--fresh')
const timestamp = new Date().toISOString()

/** sha1 of file content — used to detect whether a row's own source file
 *  actually changed, so its cached `consumers` count can be reused. */
function hashContent(content) {
  return createHash('sha1').update(content).digest('hex')
}

/**
 * Per-file cache of `consumers` counts for override rows in components.md and
 * hooks.md — the only two registries with a Consumers column. Keyed by repo-
 * relative path; a row's cached count is reused as long as its own file's
 * content hash hasn't changed. This intentionally does NOT track changes in
 * *other* files that reference this one — see the comment on countConsumers's
 * call sites for the tradeoff. Not used for `lastTouched`, which stays cheap
 * to recompute and self-corrects the one-commit-behind lag inherent to
 * reading git history from a pre-commit hook.
 */
function loadOverrideCache() {
  if (fresh || !existsSync(OVERRIDE_CACHE)) return {components: {}, hooks: {}}
  try {
    const cache = JSON.parse(readFileSync(OVERRIDE_CACHE, 'utf-8'))
    return {components: cache.components ?? {}, hooks: cache.hooks ?? {}}
  } catch {
    return {components: {}, hooks: {}}
  }
}

function saveOverrideCache(cache) {
  writeFileSync(OVERRIDE_CACHE, JSON.stringify(cache, null, 2))
}

const overrideCache = loadOverrideCache()

// ---------------------------------------------------------------------------
// Base template (node_modules/@salesforce/retail-react-app) — scanned so the
// registry covers inherited files as well as overrides.
// ---------------------------------------------------------------------------

const baseVersion = (() => {
  try {
    return JSON.parse(readFileSync(join(BASE_PKG, 'package.json'), 'utf-8')).version
  } catch {
    return null
  }
})()

// Bump when the shape of a cached base row changes (e.g. a new field added)
// so caches written by an older version of this script are not reused as-is.
const BASE_CACHE_SCHEMA = 2

function loadBaseCache() {
  if (fresh || !existsSync(BASE_CACHE)) return null
  try {
    const cache = JSON.parse(readFileSync(BASE_CACHE, 'utf-8'))
    if (cache.version !== baseVersion || cache.schema !== BASE_CACHE_SCHEMA) return null
    return cache
  } catch {
    return null
  }
}

function saveBaseCache(cache) {
  writeFileSync(
    BASE_CACHE,
    JSON.stringify({version: baseVersion, schema: BASE_CACHE_SCHEMA, ...cache}, null, 2)
  )
}

/** Path under retail-react-app for display, e.g. `app/components/header/index.jsx`. */
function toBaseRelPath(abs) {
  return relative(BASE_PKG, abs).replace(/\\/g, '/')
}

/** Folder key for matching base ↔ override. Tries the path as-is and a kebab→camel variant. */
function folderVariants(folderName) {
  const camel = folderName.includes('-') ? toCamelCase(folderName) : folderName
  const kebab = folderName.replace(/([A-Z])/g, '-$1').toLowerCase().replace(/^-/, '')
  return new Set([folderName, camel, kebab])
}

// ---------------------------------------------------------------------------
// Tier + squad classification — mirrors .claude/rules/
// ---------------------------------------------------------------------------

const TIER1_PATHS = [
  'app/theme/foundation/',
  'app/hooks/use-current-basket',
  'app/hooks/use-current-customer',
  'app/hooks/use-einstein',
  'app/hooks/use-datacloud',
  'app/hooks/use-refresh-token',
  'app/hooks/use-multi-site',
  'app/hooks/use-navigation',
  'config/default.js',
  'config/sites.js',
  'app/ssr.js',
  'app/ssr.ts',
]

const TIER2_PATHS = [
  'app/components/header/',
  'app/components/footer/',
  'app/components/drawer-menu/',
  'app/components/list-menu/',
  'app/components/seo/',
  'app/components/_app/',
  'app/components/_app-config/',
  'app/routes.tsx',
  'app/routes.jsx',
  'app/components/product-tile/',
  'app/components/product-item/',
  'app/components/display-price/',
  'app/components/image-gallery/',
  'app/components/swatch-group/',
  'app/components/recommended-products/',
  'app/components/order-summary/',
  'app/components/promo-code/',
  'app/components/pickup-or-delivery/',
  'app/theme/components/',
  'app/hooks/use-auth-modal',
  'app/hooks/use-toast',
  'app/hooks/use-modal-state',
  'app/hooks/use-intersection-observer',
  'app/hooks/use-currency',
  'app/hooks/use-dnt-notification',
  'app/hooks/use-app-origin',
  'app/hooks/use-selected-store',
]

const SQUAD_A_PATHS = [
  'app/pages/cart/',
  'app/pages/checkout/',
  'app/pages/checkout-one-click/',
  'app/pages/confirmation/',
  'app/components/sf-payments-express',
  'app/components/multiship/',
  'app/components/bonus-product-view-modal/',
  'app/hooks/use-checkout-auto-select',
  'app/hooks/use-multiship',
  'app/hooks/use-pickup-shipment',
  'app/hooks/use-sf-payments',
]

const SQUAD_B_PATHS = [
  'app/pages/home/',
  'app/pages/product-detail/',
  'app/pages/product-list/',
  'app/pages/search/',
  'app/pages/account/',
  'app/pages/store-locator/',
  'app/components/search/',
  'app/components/store-locator/',
  'app/hooks/use-product-view-modal',
  'app/hooks/use-derived-product',
  'app/hooks/use-variant',
  'app/hooks/use-wish-list',
]

function getTier(relPath) {
  if (TIER1_PATHS.some((p) => relPath.includes(p))) return '1 — Frozen'
  if (TIER2_PATHS.some((p) => relPath.includes(p))) return '2 — Protected'
  return '4 — Feature-local'
}

function getSquad(relPath) {
  if (SQUAD_A_PATHS.some((p) => relPath.includes(p))) return 'A'
  if (SQUAD_B_PATHS.some((p) => relPath.includes(p))) return 'B'
  return 'Shared'
}

// ---------------------------------------------------------------------------
// File helpers
// ---------------------------------------------------------------------------

function readFile(p) {
  try {
    return readFileSync(p, 'utf-8')
  } catch {
    return ''
  }
}

/** Path relative to repo root, e.g. overrides/app/components/header/index.tsx */
function toRelPath(abs) {
  return relative(ROOT, abs).replace(/\\/g, '/')
}

/**
 * Write a registry file only if its substantive content has changed. Compares
 * with the `Last updated:` line stripped so timestamp-only churn does not
 * trigger a write (and therefore does not get staged by the pre-commit hook).
 * Returns true if the file was (re)written.
 */
function writeIfChanged(path, content) {
  const stripTimestamp = (s) => s.replace(/^> Last updated:.*$/m, '')
  if (existsSync(path) && stripTimestamp(readFile(path)) === stripTimestamp(content)) {
    return false
  }
  writeFileSync(path, content)
  return true
}

function toPascalCase(str) {
  return str
    .replace(/^_+/, '')
    .split('-')
    .map((s) => s.charAt(0).toUpperCase() + s.slice(1))
    .join('')
}

function toCamelCase(str) {
  const p = toPascalCase(str)
  return p.charAt(0).toLowerCase() + p.slice(1)
}

function findFiles(dir, exts, exclude = []) {
  const results = []
  if (!existsSync(dir)) return results
  function walk(d) {
    for (const entry of readdirSync(d, {withFileTypes: true})) {
      const full = join(d, entry.name)
      if (entry.isDirectory()) {
        if (entry.name !== 'node_modules' && !entry.name.startsWith('.')) walk(full)
      } else if (
        exts.some((e) => entry.name.endsWith(e)) &&
        !exclude.some((p) => full.includes(p))
      ) {
        results.push(full)
      }
    }
  }
  walk(dir)
  return results
}

// ---------------------------------------------------------------------------
// Parsing helpers
// ---------------------------------------------------------------------------

/**
 * Extract the component/module-level JSDoc description from file content.
 *
 * Skips: copyright headers, JSDocs inside line-commented regions, and
 * prop-level JSDocs (those followed by an `identifier:` / `identifier?:` line).
 * Prefers an explicit `@summary` tag when present.
 * Trims to ~200 chars on a sentence boundary.
 */
function extractDescription(content) {
  // Strip whole-line comments so commented-out JSDoc blocks are ignored.
  const stripped = content
    .split('\n')
    .map((l) => (/^\s*\/\//.test(l) ? '' : l))
    .join('\n')

  const re = /\/\*\*([\s\S]*?)\*\//g
  let match
  while ((match = re.exec(stripped)) !== null) {
    const raw = match[1]
    if (raw.includes('Copyright') || raw.includes('SPDX-License')) continue

    // The next non-blank line after the JSDoc must be a real top-level
    // declaration. This rejects:
    //   - prop docs (next line is `name:` or `name?:`)
    //   - orphaned JSDocs whose subject is commented out (next line empty
    //     after we stripped line comments)
    const after = stripped.slice(match.index + match[0].length)
    const nextLine = after.split('\n').find((l) => l.trim().length > 0) ?? ''
    const isDeclaration =
      /^\s*(import\s|(export\s+)?(default\s+)?(async\s+)?(function|const|let|var|class|interface|type|enum)\s)/.test(
        nextLine
      )
    if (!isDeclaration) continue

    const lines = raw
      .split('\n')
      .map((l) => l.replace(/^\s*\*\s?/, '').trim())
      .filter((l) => l)

    // Prefer @summary if present.
    const summaryLine = lines.find((l) => l.startsWith('@summary'))
    if (summaryLine) {
      const text = summaryLine.replace(/^@summary\s*/, '').trim()
      if (text.length > 0) return truncateAtSentence(text, 200)
    }

    const desc = lines
      .filter((l) => !l.startsWith('@'))
      .join(' ')
      .replace(/\s+/g, ' ')
      .trim()
    if (desc.length > 10) return truncateAtSentence(desc, 200)
  }
  return ''
}

function truncateAtSentence(text, max) {
  if (text.length <= max) return text
  const slice = text.slice(0, max)
  const lastStop = Math.max(slice.lastIndexOf('. '), slice.lastIndexOf('; '))
  if (lastStop > max * 0.5) return slice.slice(0, lastStop + 1)
  const lastSpace = slice.lastIndexOf(' ')
  return slice.slice(0, lastSpace > 0 ? lastSpace : max) + '…'
}

/**
 * Extract top-level PropTypes prop names and whether they're required.
 * Matches only 4-space-indented lines to avoid nested shape() entries.
 * Applies to legacy `.jsx` overrides; TS components use `extractTsProps`.
 */
function extractPropTypes(content) {
  const blockMatch = content.match(/\.propTypes\s*=\s*\{([\s\S]*?)^\}/m)
  if (!blockMatch) return []

  const body = blockMatch[1]
  const props = []
  const seen = new Set()

  const re = /^ {4}(\w+)\s*:\s*PropTypes\.(\w+)([\s\S]*?)(?=\n {4}\w|\n\})/gm
  let m
  while ((m = re.exec(body)) !== null) {
    const name = m[1]
    if (seen.has(name) || name === 'children') continue
    seen.add(name)
    const typeWord = m[2]
    const rest = m[3] || ''
    const required = rest.includes('isRequired')

    const typeMap = {
      string: 'string',
      number: 'number',
      bool: 'boolean',
      func: 'function',
      array: 'array',
      object: 'object',
      node: 'node',
      element: 'element',
      shape: 'shape{…}',
      arrayOf: 'array',
      oneOf: 'enum',
      oneOfType: 'union',
      any: 'any',
    }
    const type = typeMap[typeWord] ?? typeWord
    props.push(`${name}${required ? '' : '?'}: ${type}`)
  }

  return props
}

/**
 * Extract props from a TS `type FooProps = { ... }` or `interface FooProps { ... }`
 * declaration. Best-effort: handles flat fields with simple type expressions.
 */
function extractTsProps(content) {
  const re = /(?:type|interface)\s+(\w*Props)\s*(?:=\s*)?\{([\s\S]*?)\n\}/g
  const props = []
  const seen = new Set()
  let blockMatch
  while ((blockMatch = re.exec(content)) !== null) {
    const body = blockMatch[2]
    const lineRe = /^\s{2,}(\w+)(\??):\s*([^\n;,]+)[;,]?\s*$/gm
    let m
    while ((m = lineRe.exec(body)) !== null) {
      const name = m[1]
      if (seen.has(name) || name === 'children') continue
      seen.add(name)
      const optional = m[2] === '?'
      const type = m[3].trim().slice(0, 30)
      props.push(`${name}${optional ? '?' : ''}: ${type}`)
    }
  }
  return props
}

/**
 * Extract named exports from a utility file.
 */
function extractExports(content) {
  const matches = [
    ...content.matchAll(/^export\s+(?:const|function|async\s+function)\s+(\w+)/gm),
  ]
  return [...new Set(matches.map((m) => m[1]).filter((n) => !n.startsWith('_')))]
}

/**
 * Last commit date (YYYY-MM-DD) for a tracked file. Returns '—' for paths
 * inside node_modules, untracked files, or when skipped in incremental mode.
 */
function getLastTouched(relPath, incremental) {
  if (incremental || !relPath || relPath.startsWith('node_modules/')) return '—'
  try {
    const out = execSync(`git log -1 --format=%cs -- "${relPath}"`, {
      encoding: 'utf-8',
      cwd: ROOT,
      timeout: 3000,
      stdio: ['ignore', 'pipe', 'ignore'],
    })
    return out.trim() || '—'
  } catch {
    return '—'
  }
}

/**
 * Count non-test files that import a given name (hook or util filename stem).
 * Skipped in incremental mode to keep the PostToolUse hook fast.
 */
function countConsumers(stem, incremental) {
  if (incremental) return '—'
  try {
    const count = execSync(
      `grep -rl "${stem}" "${APP}" --include="*.js" --include="*.jsx" --include="*.ts" --include="*.tsx" 2>/dev/null | grep -v "\\.test\\." | grep -v "${stem}\\." | wc -l`,
      {encoding: 'utf-8', timeout: 8000}
    )
    return parseInt(count.trim(), 10) || 0
  } catch {
    return '—'
  }
}

// ---------------------------------------------------------------------------
// Base template scanners — read once, cached by base package version.
// Each returns rows shaped like override rows so the generators can merge.
// ---------------------------------------------------------------------------

function scanBaseComponents() {
  if (!existsSync(BASE_APP)) return []
  const dir = join(BASE_APP, 'components')
  const files = findFiles(dir, ['.jsx', '.tsx'], ['.test.', '.stories.', '/shared/ui']).filter(
    (f) => basename(f).startsWith('index.')
  )
  return files.map((file) => {
    const folder = basename(dirname(file))
    const content = readFile(file)
    const props = file.endsWith('.tsx') ? extractTsProps(content) : extractPropTypes(content)
    return {
      key: folder,
      name: toPascalCase(folder),
      path: toBaseRelPath(file),
      props: props.length ? props.join(', ') : '—',
      desc: extractDescription(content) || '—',
      // Computed once per base-package version (this whole scan is skipped on
      // a cache hit — see loadBaseCache) rather than on every registry regen.
      consumers: countConsumers(folder, false),
    }
  })
}

function scanBaseHooks() {
  if (!existsSync(BASE_APP)) return []
  const dir = join(BASE_APP, 'hooks')
  const files = findFiles(dir, ['.js', '.ts'], ['.test.', '.stories.']).filter((f) => {
    const name = basename(f)
    const rel = relative(dir, f).replace(/\\/g, '/')
    const parts = rel.split('/')
    const isHookName = (n) => /^use[-A-Z]/.test(n)
    if (parts.length === 1 && isHookName(name.replace(/\.(ts|js)$/, ''))) return true
    if (parts.length === 2 && /^index\.(ts|js)$/.test(name) && isHookName(parts[0])) return true
    return false
  })
  const seen = new Set()
  return files
    .map((file) => {
      const name = basename(file)
      const parentDir = basename(dirname(file))
      const stem = /^index\.(ts|js)$/.test(name) ? parentDir : basename(file, extname(file))
      const hookName = stem.includes('-') ? toCamelCase(stem) : stem
      const content = readFile(file)
      return {
        key: stem,
        name: hookName,
        path: toBaseRelPath(file),
        desc: extractDescription(content) || '—',
        consumers: countConsumers(stem, false),
      }
    })
    .filter((r) => {
      if (seen.has(r.name)) return false
      seen.add(r.name)
      return true
    })
}

function scanBaseUtils() {
  if (!existsSync(BASE_APP)) return []
  const dir = join(BASE_APP, 'utils')
  const files = findFiles(dir, ['.js', '.ts'], ['.test.', '.stories.', 'test-utils']).filter(
    (f) => !basename(f).startsWith('index')
  )
  return files.map((file) => {
    const name = basename(file, extname(file))
    const content = readFile(file)
    const exports = extractExports(content)
    return {
      key: name,
      name,
      path: toBaseRelPath(file),
      exports: exports.length ? exports.join(', ') : '—',
      desc: extractDescription(content) || '—',
    }
  })
}

function scanBasePages() {
  if (!existsSync(BASE_APP)) return []
  const pagesDir = join(BASE_APP, 'pages')
  if (!existsSync(pagesDir)) return []
  const entries = readdirSync(pagesDir, {withFileTypes: true}).filter((e) => e.isDirectory())
  return entries.map((entry) => {
    const dir = entry.name
    const jsx = join(pagesDir, dir, 'index.jsx')
    const tsx = join(pagesDir, dir, 'index.tsx')
    const abs = existsSync(tsx) ? tsx : jsx
    return {key: dir, name: toPascalCase(dir), path: toBaseRelPath(abs)}
  })
}

const baseScan = (() => {
  const cached = loadBaseCache()
  if (cached) return cached
  if (!existsSync(BASE_APP)) {
    return {components: [], hooks: [], utils: [], pages: []}
  }
  const result = {
    components: scanBaseComponents(),
    hooks: scanBaseHooks(),
    utils: scanBaseUtils(),
    pages: scanBasePages(),
  }
  saveBaseCache(result)
  return result
})()

// ---------------------------------------------------------------------------
// Registry generators
// ---------------------------------------------------------------------------

/**
 * Consumers count for an override row, reused from `overrideCache[category]`
 * when the row's own file content hash is unchanged since the last full
 * (non-incremental) regen — skipping the repo-wide `grep` that countConsumers
 * would otherwise run. Recomputed on a hash miss (new or edited file) and
 * recorded into `nextCache` for the next run. Skipped entirely in incremental
 * mode, matching countConsumers's own '—' fast path.
 *
 * Tradeoff: a row's count only updates when *that row's own file* changes —
 * not when some other file starts/stops referencing it. Use `--fresh` to
 * force a full recompute when you need ground truth (e.g. after a large
 * refactor that changed which files reference what).
 */
function cachedConsumers({category, rel, stem, content, incremental, nextCache}) {
  if (incremental) return '—'
  const hash = hashContent(content)
  const cached = overrideCache[category][rel]
  const consumers = cached && cached.hash === hash ? cached.consumers : countConsumers(stem, false)
  nextCache[rel] = {hash, consumers}
  return consumers
}

function generateComponents(incremental = false) {
  const files = findFiles(
    join(APP, 'components'),
    ['.jsx', '.tsx'],
    ['.test.', '.stories.', '/shared/ui']
  ).filter((f) => basename(f).startsWith('index.'))

  const baseByKey = new Map(baseScan.components.map((b) => [b.key, b]))
  const nextCache = {}

  const overrideRows = files.map((file) => {
    const rel = toRelPath(file)
    const dir = basename(dirname(file))
    const name = toPascalCase(dir)
    const content = readFile(file)
    const props = file.endsWith('.tsx') || file.endsWith('.ts')
      ? extractTsProps(content)
      : extractPropTypes(content)
    // Match against base by folder name, trying camel↔kebab variants.
    const baseMatch = [...folderVariants(dir)].map((v) => baseByKey.get(v)).find(Boolean)
    if (baseMatch) baseByKey.delete(baseMatch.key)
    return {
      name,
      origin: baseMatch ? 'Override' : 'Custom',
      path: rel,
      props: props.length ? props.join(', ') : '—',
      tier: getTier(rel),
      squad: getSquad(rel),
      consumers: cachedConsumers({category: 'components', rel, stem: dir, content, incremental, nextCache}),
      lastTouched: getLastTouched(rel, incremental),
      desc: extractDescription(content) || '—',
    }
  })

  if (!incremental) {
    overrideCache.components = nextCache
    saveOverrideCache(overrideCache)
  }

  const baseRows = [...baseByKey.values()].map((b) => ({
    name: b.name,
    origin: 'Base',
    path: b.path,
    props: b.props,
    tier: getTier(`app/components/${b.key}/`),
    squad: getSquad(`app/components/${b.key}/`),
    consumers: b.consumers,
    lastTouched: '—',
    desc: b.desc,
  }))

  const rows = [...overrideRows, ...baseRows].sort((a, b) => a.name.localeCompare(b.name))

  const counts = rows.reduce(
    (acc, r) => ((acc[r.origin] = (acc[r.origin] ?? 0) + 1), acc),
    {}
  )

  const out =
    `# Component Registry\n` +
    `> Generated by \`node scripts/generateRegistry.mjs\` — do not edit manually.\n` +
    `> Last updated: ${timestamp}\n` +
    `> Base: \`@salesforce/retail-react-app@${baseVersion ?? 'unknown'}\`\n\n` +
    `| Component | Origin | Path | Props | Tier | Squad | Consumers | Last touched | Description |\n` +
    `|-----------|--------|------|-------|------|-------|-----------|--------------|-------------|\n` +
    rows
      .map(
        (r) =>
          `| ${r.name} | ${r.origin} | \`${r.path}\` | ${r.props} | ${r.tier} | ${r.squad} | ${r.consumers} | ${r.lastTouched} | ${r.desc} |`
      )
      .join('\n') +
    '\n'

  writeIfChanged(join(REGISTRY, 'components.md'), out)
  console.log(
    `  components.md  — ${rows.length} entries (Override: ${counts.Override ?? 0}, Custom: ${counts.Custom ?? 0}, Base: ${counts.Base ?? 0})`
  )
}

function generateHooks(incremental = false) {
  const hooksDir = join(APP, 'hooks')
  const files = findFiles(hooksDir, ['.js', '.ts'], ['.test.', '.stories.']).filter((f) => {
    const name = basename(f)
    const relToHooks = relative(hooksDir, f).replace(/\\/g, '/')
    const parts = relToHooks.split('/')
    const isHookName = (n) => /^use[-A-Z]/.test(n)

    // Top-level: use-kebab.ts OR useCamel.ts (Zimmermann convention)
    if (parts.length === 1 && isHookName(name.replace(/\.(ts|js)$/, ''))) return true

    // index.ts inside a use-* / use* directory
    if (parts.length === 2 && /^index\.(ts|js)$/.test(name) && isHookName(parts[0])) {
      return true
    }

    // Nested hook file inside a parent use-* / use* directory
    if (
      parts.length === 2 &&
      isHookName(name.replace(/\.(ts|js)$/, '')) &&
      isHookName(parts[0])
    ) {
      return true
    }

    return false
  })

  const baseByKey = new Map(baseScan.hooks.map((b) => [b.key, b]))
  const nextCache = {}

  const overrideRows = files.map((file) => {
    const rel = toRelPath(file)
    const name = basename(file)
    const parentDir = basename(dirname(file))
    const stem = /^index\.(ts|js)$/.test(name) ? parentDir : basename(file, extname(file))
    const hookName = stem.includes('-') ? toCamelCase(stem) : stem
    const content = readFile(file)
    const baseMatch = [...folderVariants(stem)].map((v) => baseByKey.get(v)).find(Boolean)
    if (baseMatch) baseByKey.delete(baseMatch.key)
    return {
      name: hookName,
      origin: baseMatch ? 'Override' : 'Custom',
      path: rel,
      desc: extractDescription(content) || '—',
      consumers: cachedConsumers({category: 'hooks', rel, stem, content, incremental, nextCache}),
      tier: getTier(rel),
      squad: getSquad(rel),
      lastTouched: getLastTouched(rel, incremental),
    }
  })

  if (!incremental) {
    overrideCache.hooks = nextCache
    saveOverrideCache(overrideCache)
  }

  const baseRows = [...baseByKey.values()].map((b) => ({
    name: b.name,
    origin: 'Base',
    path: b.path,
    desc: b.desc,
    consumers: b.consumers,
    tier: getTier(`app/hooks/${b.key}`),
    squad: getSquad(`app/hooks/${b.key}`),
    lastTouched: '—',
  }))

  const seen = new Set()
  const deduped = [...overrideRows, ...baseRows].filter((r) => {
    if (seen.has(r.name)) return false
    seen.add(r.name)
    return true
  })

  deduped.sort((a, b) => a.name.localeCompare(b.name))

  const counts = deduped.reduce(
    (acc, r) => ((acc[r.origin] = (acc[r.origin] ?? 0) + 1), acc),
    {}
  )

  const out =
    `# Hook Registry\n` +
    `> Generated by \`node scripts/generateRegistry.mjs\` — do not edit manually.\n` +
    `> Last updated: ${timestamp}\n` +
    `> Base: \`@salesforce/retail-react-app@${baseVersion ?? 'unknown'}\`\n\n` +
    `| Hook | Origin | Path | Description | Consumers | Tier | Squad | Last touched |\n` +
    `|------|--------|------|-------------|-----------|------|-------|--------------|\n` +
    deduped
      .map(
        (r) =>
          `| \`${r.name}\` | ${r.origin} | \`${r.path}\` | ${r.desc} | ${r.consumers} | ${r.tier} | ${r.squad} | ${r.lastTouched} |`
      )
      .join('\n') +
    '\n'

  writeIfChanged(join(REGISTRY, 'hooks.md'), out)
  console.log(
    `  hooks.md       — ${deduped.length} entries (Override: ${counts.Override ?? 0}, Custom: ${counts.Custom ?? 0}, Base: ${counts.Base ?? 0})`
  )
}

function generateUtils(incremental = false) {
  const files = findFiles(
    join(APP, 'utils'),
    ['.js', '.ts'],
    ['.test.', '.stories.', 'test-utils']
  ).filter((f) => !basename(f).startsWith('index'))

  const baseByKey = new Map(baseScan.utils.map((b) => [b.key, b]))

  const overrideRows = files.map((file) => {
    const rel = toRelPath(file)
    const name = basename(file, extname(file))
    const content = readFile(file)
    const exports = extractExports(content)
    const baseMatch = [...folderVariants(name)].map((v) => baseByKey.get(v)).find(Boolean)
    if (baseMatch) baseByKey.delete(baseMatch.key)
    return {
      name,
      origin: baseMatch ? 'Override' : 'Custom',
      path: rel,
      exports: exports.length ? exports.join(', ') : '—',
      lastTouched: getLastTouched(rel, incremental),
      desc: extractDescription(content) || '—',
    }
  })

  const baseRows = [...baseByKey.values()].map((b) => ({
    name: b.name,
    origin: 'Base',
    path: b.path,
    exports: b.exports,
    lastTouched: '—',
    desc: b.desc,
  }))

  const rows = [...overrideRows, ...baseRows].sort((a, b) => a.name.localeCompare(b.name))

  const counts = rows.reduce(
    (acc, r) => ((acc[r.origin] = (acc[r.origin] ?? 0) + 1), acc),
    {}
  )

  const out =
    `# Utility Registry\n` +
    `> Generated by \`node scripts/generateRegistry.mjs\` — do not edit manually.\n` +
    `> Last updated: ${timestamp}\n` +
    `> Base: \`@salesforce/retail-react-app@${baseVersion ?? 'unknown'}\`\n\n` +
    `| Utility | Origin | Path | Exports | Last touched | Description |\n` +
    `|---------|--------|------|---------|--------------|-------------|\n` +
    rows
      .map(
        (r) =>
          `| \`${r.name}\` | ${r.origin} | \`${r.path}\` | ${r.exports} | ${r.lastTouched} | ${r.desc} |`
      )
      .join('\n') +
    '\n'

  writeIfChanged(join(REGISTRY, 'utils.md'), out)
  console.log(
    `  utils.md       — ${rows.length} entries (Override: ${counts.Override ?? 0}, Custom: ${counts.Custom ?? 0}, Base: ${counts.Base ?? 0})`
  )
}

function generatePages() {
  const pagesDir = join(APP, 'pages')
  const overrideEntries = existsSync(pagesDir)
    ? readdirSync(pagesDir, {withFileTypes: true}).filter((e) => e.isDirectory())
    : []

  const baseByKey = new Map(baseScan.pages.map((b) => [b.key, b]))

  const overrideRows = overrideEntries.map((entry) => {
    const dir = entry.name
    const tsx = join(pagesDir, dir, 'index.tsx')
    const jsx = join(pagesDir, dir, 'index.jsx')
    const abs = existsSync(tsx) ? tsx : existsSync(jsx) ? jsx : tsx
    const baseMatch = [...folderVariants(dir)].map((v) => baseByKey.get(v)).find(Boolean)
    if (baseMatch) baseByKey.delete(baseMatch.key)
    const relPath = toRelPath(abs)
    return {
      name: toPascalCase(dir),
      origin: baseMatch ? 'Override' : 'Custom',
      path: relPath,
      squad: getSquad(`app/pages/${dir}/`),
      tier: getTier(`app/pages/${dir}/`),
      lastTouched: getLastTouched(relPath, false),
    }
  })

  const baseRows = [...baseByKey.values()].map((b) => ({
    name: b.name,
    origin: 'Base',
    path: b.path,
    squad: getSquad(`app/pages/${b.key}/`),
    tier: getTier(`app/pages/${b.key}/`),
    lastTouched: '—',
  }))

  const rows = [...overrideRows, ...baseRows].sort((a, b) => a.name.localeCompare(b.name))

  const counts = rows.reduce(
    (acc, r) => ((acc[r.origin] = (acc[r.origin] ?? 0) + 1), acc),
    {}
  )

  const out =
    `# Page Registry\n` +
    `> Generated by \`node scripts/generateRegistry.mjs\` — do not edit manually.\n` +
    `> Last updated: ${timestamp}\n` +
    `> Base: \`@salesforce/retail-react-app@${baseVersion ?? 'unknown'}\`\n\n` +
    `| Page | Origin | Path | Squad | Tier | Last touched |\n` +
    `|------|--------|------|-------|------|--------------|\n` +
    rows
      .map(
        (r) =>
          `| ${r.name} | ${r.origin} | \`${r.path}\` | ${r.squad} | ${r.tier} | ${r.lastTouched} |`
      )
      .join('\n') +
    '\n'

  writeIfChanged(join(REGISTRY, 'pages.md'), out)
  console.log(
    `  pages.md       — ${rows.length} entries (Override: ${counts.Override ?? 0}, Custom: ${counts.Custom ?? 0}, Base: ${counts.Base ?? 0})`
  )
}

/**
 * Parse a routes file into `{routePath, component, pagePath, squad, tier}`
 * rows. Local-only — does not follow spreads.
 */
function parseRoutesFile(filePath) {
  const content = readFile(filePath)

  const nameToFolder = new Map()
  for (const m of content.matchAll(
    /const\s+(\w+)\s*=\s*loadable\s*\(\s*\(\s*\)\s*=>\s*import\(\s*['"]([^'"]+)['"]/g
  )) {
    const folder = m[2].replace(/^\.\//, '').replace(/^pages\//, '')
    nameToFolder.set(m[1], folder)
  }

  const rows = []
  for (const m of content.matchAll(
    /\{\s*path:\s*['"]([^'"]+)['"][^}]*?component:\s*(\w+)/g
  )) {
    const compName = m[2]
    const folder = nameToFolder.get(compName)
    const topFolder = folder ? folder.split('/')[0] : null
    rows.push({
      routePath: m[1],
      component: compName,
      pagePath: folder ? `app/pages/${folder}/` : '—',
      squad: topFolder ? getSquad(`app/pages/${topFolder}/`) : 'Shared',
      tier: topFolder ? getTier(`app/pages/${topFolder}/`) : '4 — Feature-local',
    })
  }
  return {rows, content}
}

function generateRoutes() {
  const overrideRoutes = ['routes.tsx', 'routes.jsx'].map((f) => join(APP, f)).find(existsSync)
  const baseRoutes = ['routes.jsx', 'routes.tsx'].map((f) => join(BASE_APP, f)).find(existsSync)
  const primary = overrideRoutes ?? baseRoutes
  if (!primary) {
    writeIfChanged(
      join(REGISTRY, 'routes.md'),
      `# Route Registry\n> No routes file found.\n`
    )
    console.log(`  routes.md      — 0 entries`)
    return
  }

  const {rows: localRows, content: primaryContent} = parseRoutesFile(primary)
  const localTagged = localRows.map((r) => ({...r, source: overrideRoutes ? 'Override' : 'Base'}))

  // Detect spread of base routes: `import {routes as Alias} from '@salesforce/retail-react-app/app/routes'`
  // (or no alias) followed by `...Alias` inside the routes array.
  let inheritedRows = []
  if (overrideRoutes && baseRoutes) {
    const aliasMatch = primaryContent.match(
      /import\s*\{([^}]*\broutes\b[^}]*)\}\s*from\s*['"]@salesforce\/retail-react-app\/app\/routes['"]/
    )
    if (aliasMatch) {
      const aliasGroup = aliasMatch[1]
      const renamed = aliasGroup.match(/\broutes\s+as\s+(\w+)/)
      const alias = renamed ? renamed[1] : 'routes'
      if (new RegExp(`\\.\\.\\.${alias}\\b`).test(primaryContent)) {
        const {rows} = parseRoutesFile(baseRoutes)
        inheritedRows = rows.map((r) => ({...r, source: 'Inherited'}))
      }
    }
  }

  // Local routes declared before `..._routes` shadow inherited ones at the same URL.
  // Drop the inherited duplicate so the table reflects runtime behaviour.
  const localUrls = new Set(localTagged.map((r) => r.routePath))
  const all = [...localTagged, ...inheritedRows.filter((r) => !localUrls.has(r.routePath))].sort(
    (a, b) => a.routePath.localeCompare(b.routePath)
  )

  const counts = all.reduce(
    (acc, r) => ((acc[r.source] = (acc[r.source] ?? 0) + 1), acc),
    {}
  )

  const filePath = overrideRoutes ? toRelPath(primary) : toBaseRelPath(primary)
  const out =
    `# Route Registry\n` +
    `> Generated by \`node scripts/generateRegistry.mjs\` — do not edit manually.\n` +
    `> Last updated: ${timestamp}\n` +
    `> Source: \`${filePath}\`${inheritedRows.length ? ` (+ inherited base routes)` : ''}\n` +
    `> Base: \`@salesforce/retail-react-app@${baseVersion ?? 'unknown'}\`\n\n` +
    `| URL | Component | Page folder | Source | Squad | Tier |\n` +
    `|-----|-----------|-------------|--------|-------|------|\n` +
    all
      .map(
        (r) =>
          `| \`${r.routePath}\` | ${r.component} | \`${r.pagePath}\` | ${r.source} | ${r.squad} | ${r.tier} |`
      )
      .join('\n') +
    '\n'

  writeIfChanged(join(REGISTRY, 'routes.md'), out)
  const breakdown = Object.entries(counts)
    .map(([k, v]) => `${k}: ${v}`)
    .join(', ')
  console.log(`  routes.md      — ${all.length} entries (${breakdown})`)
}

// ---------------------------------------------------------------------------
// Entry point
// ---------------------------------------------------------------------------

if (fileArg) {
  const rel = fileArg.replace(/\\/g, '/')
  if (rel.includes('/components/')) {
    process.stdout.write('Updating components registry... ')
    generateComponents(true)
  } else if (rel.includes('/hooks/')) {
    process.stdout.write('Updating hooks registry... ')
    generateHooks(true)
  } else if (rel.includes('/utils/')) {
    process.stdout.write('Updating utils registry... ')
    generateUtils(true)
  } else if (rel.includes('/pages/')) {
    process.stdout.write('Updating pages registry... ')
    generatePages()
  } else if (/\/routes\.(tsx|jsx|ts|js)$/.test(rel)) {
    process.stdout.write('Updating routes registry... ')
    generateRoutes()
  } else {
    process.exit(0)
  }
} else {
  console.log('Generating Claude Code registry...')
  generateComponents(false)
  generateHooks(false)
  generateUtils(false)
  generatePages()
  generateRoutes()
  console.log('Done.')
}

